'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var namedtypedtuple = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof namedtypedtuple, 'function', 'main export is a function' );
	t.end();
});

tape( 'a tuple has a `subarray` method', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point();

	t.strictEqual( hasProp( p, 'subarray' ), true, 'returns expected value' );
	t.strictEqual( isFunction( p.subarray ), true, 'returns expected value' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a tuple instance', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.subarray.call( value );
		};
	}
});

tape( 'the method returns a new typed array view over the same buffer', function test( t ) {
	var Point;
	var arr;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	arr = p.subarray();

	t.strictEqual( arr.length, 3, 'returns expected value' );
	t.strictEqual( arr[ 0 ], 1, 'returns expected value' );
	t.strictEqual( arr[ 1 ], 2, 'returns expected value' );
	t.strictEqual( arr[ 2 ], 3, 'returns expected value' );
	t.strictEqual( arr.buffer, p.buffer, 'returns expected value' );

	t.end();
});

tape( 'the method supports specifying a beginning index', function test( t ) {
	var Point;
	var arr;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	arr = p.subarray( 1 );

	t.strictEqual( arr.length, 2, 'returns expected value' );
	t.strictEqual( arr[ 0 ], 2, 'returns expected value' );
	t.strictEqual( arr[ 1 ], 3, 'returns expected value' );

	t.end();
});

tape( 'the method supports specifying an end index', function test( t ) {
	var Point;
	var arr;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	arr = p.subarray( 0, 2 );

	t.strictEqual( arr.length, 2, 'returns expected value' );
	t.strictEqual( arr[ 0 ], 1, 'returns expected value' );
	t.strictEqual( arr[ 1 ], 2, 'returns expected value' );

	t.end();
});

tape( 'the method supports negative indices', function test( t ) {
	var Point;
	var arr;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	arr = p.subarray( -p.length, -1 );

	t.strictEqual( arr.length, 2, 'returns expected value' );
	t.strictEqual( arr[ 0 ], 1, 'returns expected value' );
	t.strictEqual( arr[ 1 ], 2, 'returns expected value' );

	t.end();
});

tape( 'the method returns an empty typed array if unable to resolve indices to a non-empty range', function test( t ) {
	var Point;
	var arr;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	arr = p.subarray( 10, -1 );

	t.strictEqual( arr.length, 0, 'returns expected value' );

	t.end();
});

tape( 'the returned view shares the same underlying buffer', function test( t ) {
	var Point;
	var arr;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	arr = p.subarray( 1 );

	// Modifying the view modifies the original:
	arr[ 0 ] = 99;
	t.strictEqual( p[ 1 ], 99, 'returns expected value' );

	// Field values reflect the update:
	t.strictEqual( p.x, 1, 'returns expected value' );
	t.strictEqual( p.y, 99, 'returns expected value' );
	t.strictEqual( p.z, 3, 'returns expected value' );

	t.end();
});
